"""Order total recomputation migrated from Meridian CRM 4.2 CRMScript."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENT = Decimal("0.01")
_HUNDRED = Decimal("100")


def _number(value: Any) -> Decimal:
    """Apply legacy empty/missing numeric coercion without float artifacts."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(value)


def _money(value: Decimal) -> Decimal:
    """Round a monetary value half-up to cents."""
    rounded = value.quantize(_CENT, rounding=ROUND_HALF_UP)
    return Decimal("0.00") if rounded == 0 else rounded


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    """Recompute one order and its lines using the legacy job's semantics."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    audits: list[tuple[str, Any]] = []

    # The legacy schema's numeric bounds fit comfortably within this precision.
    with localcontext() as context:
        context.prec = 64

        total = Decimal(0)

        for line in new_lines:
            if line.get("DEL_FLG") == "Y":
                continue

            extended = _money(
                _number(line.get("QTY", "")) * _number(line.get("UNIT_PRC", ""))
            )
            line["EXT_AMT"] = float(extended)
            total += extended

        discount = _number(order.get("DISC_PCT", ""))
        discounted = _money(total * (_HUNDRED - discount) / _HUNDRED)

        incoming_total = _number(order.get("TOT_AMT", ""))
        new_order["TOT_AMT"] = float(discounted)

        if incoming_total != discounted:
            audits.append(("ORD_RETOTAL", order.get("ORD_ID", "")))

    return new_order, new_lines, audits
